const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function eeGetInfo(obj) {
    return new Promise((resolve, reject) => obj.getInfo(resolve, reject));
  }

  try {
    // 1. Geometry & Time Definitions
    const lon = -112.246886;
    const lat = 34.498828;
    const radiusMeters = 50 * 1609.344; // 50 miles
    const region = ee.Geometry.Point([lon, lat]).buffer(radiusMeters);
    const start = ee.Date('2017-06-20');
    const end = ee.Date('2017-07-01'); // end-exclusive

    // Helper to get merged Terra + Aqua collections for a date range
    function mergedCol(s, e) {
      const terra = ee.ImageCollection('MODIS/061/MOD14A1').filterDate(s, e).filterBounds(region);
      const aqua = ee.ImageCollection('MODIS/061/MYD14A1').filterDate(s, e).filterBounds(region);
      return { terra, aqua, merged: terra.merge(aqua) };
    }

    // 2. Data Acquisition & Check
    let { terra, aqua, merged } = mergedCol(start, end);
    let terraCount = await eeGetInfo(terra.size());
    let aquaCount = await eeGetInfo(aqua.size());
    let mergedCount = terraCount + aquaCount;

    if (mergedCount === 0) {
      // Fallback: widen the date window by ±3 days
      const start2 = start.advance(-3, 'day');
      const end2 = end.advance(3, 'day');
      ({ terra, aqua, merged } = mergedCol(start2, end2));
      terraCount = await eeGetInfo(terra.size());
      aquaCount = await eeGetInfo(aqua.size());
      mergedCount = terraCount + aquaCount;
      if (mergedCount === 0) {
        console.log('Images (Terra, Aqua): 0, 0');
        console.log('Expanded window also empty.');
        console.log('C1');
        return;
      } else {
        console.log('Note: Using expanded window (±3 days) due to empty initial window.');
      }
    }

    // 3. Processing: valid-pixel map (FireMask > 0), fire map (FireMask >= 7 [low+ nominal+ high conf])
    const validAny = merged.map(img => img.select('FireMask').gt(0).rename('valid')).max();
    const fireAny = merged.map(img => img.select('FireMask').gte(7).rename('fire')).max();

    // Pixel counts
    const potentialCount = await eeGetInfo(
      ee.Image.constant(1).clip(region).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('constant')
    );

    const validCount = await eeGetInfo(
      validAny.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('valid')
    );

    const fireCount = await eeGetInfo(
      fireAny.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('fire')
    );

    // 4. Validation
    console.log(`Date range: 2017-06-20 to 2017-06-30`);
    console.log(`Images (Terra, Aqua): ${terraCount}, ${aquaCount}`);
    console.log(`Potential pixels (~1km): ${potentialCount || 0}`);
    console.log(`Valid pixels (processed): ${validCount || 0}`);
    console.log(`Fire pixels (any day, conf≥low): ${fireCount || 0}`);

    if (validCount === null || fireCount === null || isNaN(validCount) || isNaN(fireCount)) {
      console.log('C3');
      return;
    }
    if ((validCount || 0) === 0) {
      console.log('C2');
      return;
    }

    // 5. Final Answer
    if ((fireCount || 0) > 0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    try {
      console.log(`Error: ${String(err).slice(0, 120)}`);
    } catch (_e) {}
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
